// Combine raw definitions and extended words into unified, high-speed indexed dataset
// Offensive or adult words are hidden to keep the site family-friendly and ad-safe (Google Ads / AdSense policies).
// Remove entries here if you want a complete Scrabble dictionary.
export const BLOCKED_WORDS = new Set(["BITCH", "CHINK", "SLUTS", "WHORE", "RAPED", "RAPER", "RAPES", "PENIS"]);

export function buildWordDictionary(): WordEntry[] {
  const definitionMap = new Map<string, [string, string, string?]>();
  for (const [w, def, pos, ex] of RAW_WORDS_DATA) {
    definitionMap.set(w.toUpperCase(), [def, pos, ex]);
  }

  const allWordSet = new Set<string>();
  RAW_WORDS_DATA.forEach(([w]) => allWordSet.add(w.toUpperCase()));
  EXTENDED_5_LETTER_WORDS.forEach((w) => allWordSet.add(w.toUpperCase()));

  const wordList: WordEntry[] = [];

  // Famous Wordle starters
  const WORDLE_TOP_STARTERS = new Set([
    "ADIEU", "SOARE", "ROAST", "CRANE", "SLATE", "AUDIO", "TRACE", "RAISE",
    "TEARS", "LATER", "ARISE", "STARE", "SALET", "ORATE", "PILOT", "LEARN",
    "HEART", "STONE", "CLEAN", "SHINE", "GUIDE", "POINT", "PLANT", "DREAM"
  ]);

  for (const word of allWordSet) {
    if (word.length !== 5 || !/^[A-Z]{5}$/.test(word)) continue;
    if (BLOCKED_WORDS.has(word)) continue;

    const defTuple = definitionMap.get(word);
    const scrabble = calculateScrabbleScore(word);
    const wwf = calculateWwfScore(word);
    const vowels = countVowels(word);
    const isPal = isPalindrome(word);
    const isDouble = hasDoubleLetters(word);

    const tags: string[] = [];
    if (isPal) tags.push("palindrome");
    if (vowels === 0) tags.push("no-vowels");
    if (vowels >= 3) tags.push("vowel-rich");
    if (isDouble) tags.push("double-letters");
    if (scrabble >= 15) tags.push("high-scoring");
    if (WORDLE_TOP_STARTERS.has(word)) tags.push("wordle-top");

    const defaultDef = defTuple
      ? defTuple[0]
      : `Valid 5-letter English word for Wordle, Scrabble, and word games.`;
    const defaultPos = defTuple ? defTuple[1] : "vocabulary";
    const defaultEx = defTuple ? defTuple[2] : undefined;

    wordList.push({
      word,
      definition: defaultDef,
      partOfSpeech: defaultPos,
      example: defaultEx,
      scrabbleScore: scrabble,
      wwfScore: wwf,
      vowels,
      isCommon: Boolean(defTuple),
      isWordleAnswer: Boolean(defTuple) || WORDLE_TOP_STARTERS.has(word),
      tags
    });
  }

  // Sort alphabetically initially
  return wordList.sort((a, b) => a.word.localeCompare(b.word));
}

export const ALL_WORDS: WordEntry[] = buildWordDictionary();
export const WORDS_SET = new Set(ALL_WORDS.map((w) => w.word));
